// Original MACD algorithm that uses mesh information to fix manifold point normals after the manifold is built.
// @todo(chaos): remove this when the new version is well tested.

inline TAABB<T, 3> InverseTransformedAABBHelper2(const TAABB<T, 3>& AABB, const TRigidTransform<U, 3>& SpaceTransform)
{
	// Full and empty bounds do not transform
	if (AABB.IsFull() || AABB.IsEmpty())
	{
		return AABB;
	}

	// NOTE: This is required for TAABB3<float> and TAABB3<double> with either float or double transform
	const TVec3<T> InvTranslation = -TVec3<T>(SpaceTransform.GetTranslation());
	const TRotation3<T> InvRotation = TRotation3<T>(SpaceTransform.GetRotation()).Inverse();
	const TVec3<T> InvScale = TVec3<T>(1) / TVec3<T>(SpaceTransform.GetScale3D());

	// Center-relative scaled verts
	const TVec3<T> Extent = T(0.5) * (AABB.Max() - AABB.Min());
	const TVec3<T> Vert0 = TVec3<T>(Extent.X, Extent.Y, Extent.Z);
	const TVec3<T> Vert1 = TVec3<T>(Extent.X, Extent.Y, -Extent.Z);
	const TVec3<T> Vert2 = TVec3<T>(Extent.X, -Extent.Y, Extent.Z);
	const TVec3<T> Vert3 = TVec3<T>(Extent.X, -Extent.Y, -Extent.Z);

	// Rotated center-relative scaled verts
	// Note: Scale may be negative but it does not affect the bounds calculation
	const TVec3<T> RVert0 = InvScale * (InvRotation * Vert0);
	const TVec3<T> RVert1 = InvScale * (InvRotation * Vert1);
	const TVec3<T> RVert2 = InvScale * (InvRotation * Vert2);
	const TVec3<T> RVert3 = InvScale * (InvRotation * Vert3);

	// Max rotated scaled center-relative extent
	TVec3<T> RExtent = TVec3<T>(0);
	RExtent = TVec3<T>::Max(RExtent, RVert0.GetAbs());
	RExtent = TVec3<T>::Max(RExtent, RVert1.GetAbs());
	RExtent = TVec3<T>::Max(RExtent, RVert2.GetAbs());
	RExtent = TVec3<T>::Max(RExtent, RVert3.GetAbs());

	// Transformed center
	// NOTE: This is where positive/negative scales matters
	const TVec3<T> Center = T(0.5) * (AABB.Min() + AABB.Max());
	const TVec3<T> TCenter =  InvScale * (InvRotation * (InvTranslation + Center));

	// Transformed bounds
	return TAABB<T, 3>(TCenter - RExtent, TCenter + RExtent);
}

FORCEINLINE bool Intersects(const TAABB<TReal, d>& Other) const
{
	for (int32 i = 0; i < d; ++i)
	{
		if (Other.Max()[i] < MMin[i] || Other.Min()[i] > MMax[i])
			return false;
	}
	return true;
}

FORCEINLINE TAABB<T, d>& Thicken(const T Thickness)
{
	MMin -= TVector<T, d>(Thickness);
	MMax += TVector<T, d>(Thickness);
	return *this;
}

void FTriangleMeshImplicitObject::CollectTriangles(const FAABB3& MeshQueryBounds, const FRigidTransform3& MeshToObjectTransform, const FAABB3& ObjectBounds, Private::FMeshContactGenerator& Collector) const
{
	TArray<int32> OverlapIndices;
	FindOverlappingTriangles(MeshQueryBounds, OverlapIndices);

	const bool bStandardWinding = ((MeshToObjectTransform.GetScale3D().X * MeshToObjectTransform.GetScale3D().Y * MeshToObjectTransform.GetScale3D().Z) >= FReal(0));

	Collector.BeginCollect(OverlapIndices.Num());

	for (int32 OverlapIndex = 0; OverlapIndex < OverlapIndices.Num(); ++OverlapIndex)
	{
		const int32 TriangleIndex = OverlapIndices[OverlapIndex];
		FTriangle Triangle;
		int32 VertexIndex0, VertexIndex1, VertexIndex2;
		GetTransformedTriangle(TriangleIndex, MeshToObjectTransform, Triangle, VertexIndex0, VertexIndex1, VertexIndex2);

		if (!bStandardWinding)
		{
			Triangle.ReverseWinding();
			Swap(VertexIndex1, VertexIndex2);
		}

		const FAABB3 TriBounds = FAABB3::FromPoints(Triangle.GetVertex(0), Triangle.GetVertex(1), Triangle.GetVertex(2));
		if (TriBounds.Intersects(ObjectBounds))
		{
			Collector.AddTriangle(Triangle, TriangleIndex, VertexIndex0, VertexIndex1, VertexIndex2);
		}
	}

	Collector.EndCollect();
}

template <typename IdxType, typename ParticlesType>
inline void TriangleMeshTransformVertsHelper(const FRigidTransform3& Transform, int32 TriIdx, const ParticlesType& Particles,
	const TArray<TVector<IdxType, 3>>& Elements, FVec3& OutA, FVec3& OutB, FVec3& OutC,
	int32& OutVertexIndexA, int32& OutVertexIndexB, int32& OutVertexIndexC)
{
	const int32 VertexIndexA = Elements[TriIdx][0];
	const int32 VertexIndexB = Elements[TriIdx][1];
	const int32 VertexIndexC = Elements[TriIdx][2];
	// Note: deliberately using scaled transform here. See VisitTriangles
	OutA = Transform.TransformPosition(FVector(Particles.GetX(VertexIndexA)));
	OutB = Transform.TransformPosition(FVector(Particles.GetX(VertexIndexB)));
	OutC = Transform.TransformPosition(FVector(Particles.GetX(VertexIndexC)));
	OutVertexIndexA = VertexIndexA;
	OutVertexIndexB = VertexIndexB;
	OutVertexIndexC = VertexIndexC;
}

template<typename TriangleVisitor>
void VisitTriangles(const FAABB3& QueryBounds, const FRigidTransform3& QueryTransform, const TriangleVisitor& Visitor) const
{
	TArray<int32> OverlapIndices;
	FindOverlappingTriangles(QueryBounds, OverlapIndices);

	const bool bStandardWinding = ((QueryTransform.GetScale3D().X * QueryTransform.GetScale3D().Y * QueryTransform.GetScale3D().Z) >= FReal(0));

	for (int32 OverlapIndex = 0; OverlapIndex < OverlapIndices.Num(); ++OverlapIndex)
	{
		const int32 TriangleIndex = OverlapIndices[OverlapIndex];
		FTriangle Triangle;
		int32 VertexIndex0, VertexIndex1, VertexIndex2;
		GetTransformedTriangle(TriangleIndex, QueryTransform, Triangle, VertexIndex0, VertexIndex1, VertexIndex2);

		if (!bStandardWinding)
		{
			Triangle.ReverseWinding();
			Swap(VertexIndex1, VertexIndex2);
		}

		Visitor(Triangle, TriangleIndex, VertexIndex0, VertexIndex1, VertexIndex2);
	}

